"""Invoice arithmetic shared by checkout and reporting."""

def calculate_total(items: list[float], *, discount: float = 0.0) -> float:
    if not 0 <= discount <= 1:
        raise ValueError("discount must be between zero and one")
    return round(sum(items) * (1 - discount), 2)

def tax(total: float, rate: float = 0.2) -> float:
    return round(total * rate, 2)

from billing import calculate_total, tax

def checkout(items):
    subtotal = calculate_total(items, discount=0.1)
    return subtotal + tax(subtotal)

